65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 AddressNormalizer addressNormalizer,
106	                                 EmailNormalizer emailNormalizer) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	        this.telephoneNormalizer = telephoneNormalizer;
112	        this.addressNormalizer = addressNormalizer;
113	        this.emailNormalizer = emailNormalizer;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        owners.forEach(this::populateHouseholdMemberCount);
129	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        populateHouseholdMemberCount(owner);
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        normalizeAndValidate(ownerFieldsDto);
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
150	        owner.setNamesakeCount(countNamesakes(owner));
151	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
152	        assignHousehold(owner, ownerFieldsDto);
153	        this.clinicService.saveOwner(owner);
154	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
155	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
156	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
157	        populateHouseholdMemberCount(owner);
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    /**
165	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
166	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
167	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
168	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
169	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
170	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
171	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
172	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
173	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
174	     *
175	     * @param ownerFieldsDto the incoming owner payload, mutated in place
176	     * @throws MissingOwnerFieldsException if any required field is missing or blank
177	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
178	     */
179	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
180	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
181	        validateRequiredFields(ownerFieldsDto);
182	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
183	        ownerFieldsDto.setTelephone(telephone);
184	        requireUniqueTelephone(telephone);
185	        requireUniqueHousehold(ownerFieldsDto);
186	        requireCityHasCapacity(ownerFieldsDto.getCity());
187	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
188	        ownerFieldsDto.setRegistrationDate(registrationDate);
189	        requireDailyLimitNotReached(registrationDate);
190	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
191	        ownerFieldsDto.setEmail(email);
192	        requireUniqueEmail(email);
193	    }
194	
195	    /**
196	     * Rejects creating an owner whose normalized (lower-cased) email is already used by another owner. Existing owners'
197	     * stored emails are normalized the same way before comparison, so the rule holds regardless of the case the email
198	     * was originally supplied in. A missing (blank or {@code null}) email is never rejected, since the field is
199	     * optional.
200	     *
201	     * @param email the normalized email of the owner being created, may be {@code null}
202	     * @throws DuplicateEmailException if any existing owner already uses the same normalized email
203	     */
204	    private void requireUniqueEmail(String email) {
205	        if (email == null || email.isBlank()) {
206	            return;
207	        }
208	        boolean inUse = this.clinicService.findAllOwners().stream()
209	            .map(existing -> emailNormalizer.normalize(existing.getEmail()))
210	            .anyMatch(email::equals);
211	        if (inUse) {
212	            throw new DuplicateEmailException("email is already in use by another owner");
213	        }
214	    }
215	
216	    /**
217	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
218	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
219	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
220	     *
221	     * @param ownerFieldsDto the incoming owner payload
222	     * @return the effective registration date rolled forward onto a business day
223	     */
224	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
225	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
226	        if (effective == null) {
227	            effective = LocalDate.now();
228	        }
229	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
230	            effective = effective.plusDays(1);
231	        }
232	        return effective;
233	    }
234	
235	    /**
236	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
237	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
238	     * further owner may be created for that day.
239	     *
240	     * @param registrationDate the adjusted business-day registration date of the owner being created
241	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
242	     */
243	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
244	        long createdThatDay = this.clinicService.findAllOwners().stream()
245	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
246	            .count();
247	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
248	            throw new DailyOwnerLimitExceededException(
249	                "the maximum number of owners for today has already been reached");
250	        }
251	    }
252	
253	    /**
254	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
255	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
256	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
257	     * reflects only owners that predate it.
258	     *
259	     * @param registrationDate the adjusted business-day registration date of the owner being created
260	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
261	     */
262	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
263	        long createdThatDay = this.clinicService.findAllOwners().stream()
264	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
265	            .count();
266	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
267	    }
268	
269	    /**
270	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
271	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
272	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
273	     * city (e.g. {@code LON-SMI-0007}).
274	     *
275	     * @param city     the owner's city
276	     * @param lastName the owner's last name
277	     * @return the generated customer code
278	     */
279	    private String generateCustomerCode(String city, String lastName) {
280	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
281	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
282	        int sequence = (int) this.clinicService.findAllOwners().stream()
283	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
284	            .count() + 1;
285	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
286	    }
287	
288	    /**
289	     * Counts how many existing owners already share the given owner's first and last name, compared
290	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
291	     * create; it is zero when the owner's name is unique.
292	     *
293	     * @param owner the newly mapped owner about to be saved
294	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
295	     */
296	    private int countNamesakes(Owner owner) {
297	        String firstName = owner.getFirstName();
298	        String lastName = owner.getLastName();
299	        return (int) this.clinicService.findAllOwners().stream()
300	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
301	                && lastName.equalsIgnoreCase(existing.getLastName()))
302	            .count();
303	    }
304	
305	    /**
306	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
307	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
308	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
309	     *
310	     * @param ownerFieldsDto the owner payload to validate
311	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
312	     */
313	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
314	        List<String> missingFields = new ArrayList<>();
315	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
316	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
317	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
318	        requireText(missingFields, "city", ownerFieldsDto.getCity());
319	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
320	        if (!missingFields.isEmpty()) {
321	            throw new MissingOwnerFieldsException(missingFields);
322	        }
323	    }
324	
325	    private void requireText(List<String> missingFields, String fieldName, String value) {
326	        if (value == null || value.isBlank()) {
327	            missingFields.add(fieldName);
328	        }
329	    }
330	
331	    /**
332	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
333	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
334	     * originally formatted.
335	     *
336	     * @param telephone the normalized telephone of the owner being created
337	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
338	     */
339	    private void requireUniqueTelephone(String telephone) {
340	        boolean inUse = this.clinicService.findAllOwners().stream()
341	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
342	            .anyMatch(telephone::equals);
343	        if (inUse) {
344	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
345	        }
346	    }
347	
348	    /**
349	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
350	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
351	     *
352	     * @param city the city of the owner being created
353	     * @throws OwnerCityFullException if the city already contains 50 or more owners
354	     */
355	    private void requireCityHasCapacity(String city) {
356	        long cityOwners = this.clinicService.findAllOwners().stream()
357	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
358	            .count();
359	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
360	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
361	        }
362	    }
363	
364	    /**
365	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
366	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
367	     *
368	     * @param ownerFieldsDto the incoming owner payload
369	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
370	     *                                 set {@code sharesHousehold}
371	     */
372	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
373	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
374	            return;
375	        }
376	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
377	            throw new DuplicateOwnerException(
378	                "an owner with the same last name and address already exists in this household");
379	        }
380	    }
381	
382	    /**
383	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
384	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
385	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
386	     * incidental formatting differences and abbreviation variants do not affect membership.
387	     *
388	     * @param ownerFieldsDto the incoming owner payload
389	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
390	     *         them; empty when none match
391	     */
392	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
393	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
394	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
395	        return this.clinicService.findAllOwners().stream()
396	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
397	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
398	            .toList();
399	    }
400	
401	    /**
402	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
403	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
404	     *
405	     * @param value the raw field value, may be {@code null}
406	     * @return the whitespace-collapsed value, or an empty string when {@code null}
407	     */
408	    private String collapseWhitespace(String value) {
409	        if (value == null) {
410	            return "";
411	        }
412	        return value.strip().replaceAll("\\s+", " ");
413	    }
414	
415	    /**
416	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
417	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
418	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
419	     * identifier is derived deterministically from the household's last name and address, so every member of the same
420	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
421	     * feature and still lack the identifier are backfilled so the whole household shares it.
422	     *
423	     * @param owner          the newly mapped owner about to be saved
424	     * @param ownerFieldsDto the incoming owner payload
425	     */
426	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
427	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
428	            return;
429	        }
430	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
431	        if (members.isEmpty()) {
432	            return;
433	        }
434	        String householdId = generateHouseholdId(ownerFieldsDto);
435	        owner.setHouseholdId(householdId);
436	        for (Owner member : members) {
437	            if (!householdId.equals(member.getHouseholdId())) {
438	                member.setHouseholdId(householdId);
439	                this.clinicService.saveOwner(member);
440	            }
441	        }
442	    }
443	
444	    /**
445	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
446	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
447	     * of those fields, it is identical for every owner in the same household and never changes over time.
448	     *
449	     * @param ownerFieldsDto the incoming owner payload
450	     * @return the household identifier
451	     */
452	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
453	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
454	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
455	        try {
456	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
457	            StringBuilder hex = new StringBuilder();
458	            for (int i = 0; i < 6; i++) {
459	                hex.append(String.format("%02X", digest[i]));
460	            }
461	            return "HH-" + hex;
462	        } catch (NoSuchAlgorithmException ex) {
463	            throw new IllegalStateException("SHA-256 is not available", ex);
464	        }
465	    }
466	
467	    /**
468	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
469	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
470	     * household is counted as a household of one.
471	     *
472	     * @param owner the owner whose household size should be resolved
473	     */
474	    private void populateHouseholdMemberCount(Owner owner) {
475	        String householdId = owner.getHouseholdId();
476	        if (householdId == null) {
477	            owner.setHouseholdMemberCount(1);
478	            return;
479	        }
480	        long members = this.clinicService.findAllOwners().stream()
481	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
482	            .count();
483	        owner.setHouseholdMemberCount((int) members);
484	    }
485	
486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Override
488	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
489	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
490	        if (currentOwner == null) {
491	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
492	        }
493	        currentOwner.setAddress(ownerFieldsDto.getAddress());
494	        currentOwner.setCity(ownerFieldsDto.getCity());
495	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
496	        currentOwner.setLastName(ownerFieldsDto.getLastName());
497	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
498	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
499	        this.clinicService.saveOwner(currentOwner);
500	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
501	    }
502	
503	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
504	    @Transactional
505	    @Override
506	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
507	        Owner owner = this.clinicService.findOwnerById(ownerId);
508	        if (owner == null) {
509	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
510	        }
511	        this.clinicService.deleteOwner(owner);
512	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
513	    }
514	
515	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
516	    @Override
517	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
518	        Owner owner = this.clinicService.findOwnerById(ownerId);
519	        if (owner == null) {
520	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
